import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"双调·殿前欢秋日湖上","description":"","frontmatter":{"title":"双调·殿前欢秋日湖上","date":"2026-11-11T00:00:00.000Z","seq":1,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/双调·殿前欢秋日湖上.md","filePath":"blogs/元曲·张可久/双调·殿前欢秋日湖上.md"}'),o={name:"blogs/元曲·张可久/双调·殿前欢秋日湖上.md"};function c(l,a,n,m,z,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="双调·殿前欢秋日湖上" tabindex="-1">双调·殿前欢秋日湖上 <a class="header-anchor" href="#双调·殿前欢秋日湖上" aria-label="Permalink to &quot;双调·殿前欢秋日湖上&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">倚吟篷，障西风十里锦芙蓉。</p><p class="poem-stanza">照沧浪似入桃源桐，欠个渔翁。</p><p class="poem-stanza">冰泉泻翠筒，玉液浮银瓮，罗袖擎金凤。</p><p class="poem-stanza">团香弄粉，泛绿依红。</p><p class="poem-stanza">次酸斋韵二首钓鱼台，十年不上野鸥猜。</p><p class="poem-stanza">白云来往青山在，对酒开怀。</p><p class="poem-stanza">欠伊周济世才，犯刘阮贪杯戒，还李杜吟诗债。</p><p class="poem-stanza">酸斋笑我，我笑酸斋。</p><p class="poem-stanza">唤归来，西湖山上野猿哀。</p><p class="poem-stanza">二十年多少风流怪，花落花开。</p><p class="poem-stanza">望云霄拜将台，袖星斗安邦策，破烟月迷魂寨。</p><p class="poem-stanza">酸斋笑我，我笑酸斋。</p><p class="poem-stanza">离思二首夜啼乌，柳枝和月翠扶疏。</p><p class="poem-stanza">绣鞋香染莓苔露，搔首踟蹰。</p><p class="poem-stanza">灯残瘦影孤，花落流年度，春去佳期误。</p><p class="poem-stanza">离鸾有恨，过雁无书。</p><p class="poem-stanza">月笼沙，十年心事付琵琶。</p><p class="poem-stanza">相思懒看帏屏画，人在天涯。</p><p class="poem-stanza">春残豆蔻花，情寄鸳鸯帕，香冷荼コ架。</p><p class="poem-stanza">旧游台榭，晓梦窗纱。</p><p class="poem-stanza">西湖晚晴总宜船，绿情红意雨余天。</p><p class="poem-stanza">盈盈皓月明如练，棹举冰田。</p><p class="poem-stanza">神仙太乙莲，图画崔徽面，才思班姬扇。</p><p class="poem-stanza">新诗象管，古调冰弦。</p><p class="poem-stanza">客中二首望长安，前程渺渺鬓斑斑。</p><p class="poem-stanza">南来北往随征雁，行路艰难。</p><p class="poem-stanza">青泥小剑关，红叶湓江岸，白草连云栈。</p><p class="poem-stanza">功名半纸，风雪千山。</p><p class="poem-stanza">锦缠头，粉筝低按舞《凉州》。</p><p class="poem-stanza">佳人一去春残后，香冷云兜。</p><p class="poem-stanza">晴山翠黛愁，绿水罗裙皱，细柳宫腰瘦。</p><p class="poem-stanza">梨花暮雨，燕子空楼。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
